import time

class RateLimiter:
    """
    A Rate Limiter using a dictionary to track the number of requests per time window in a sliding scale.
    This approach utilizes a hashmap to maintain counts of requests made per second, allowing efficient space management and lookup.
    """

    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.request_counts = {}
        self.start_time = time.time()

    def allow(self) -> bool:
        current_time = time.time()
        current_window = int(current_time // self.window_seconds)

        if current_window not in self.request_counts:
            self.request_counts[current_window] = 0

        # Reset counts for old windows
        for window in list(self.request_counts.keys()):
            if window < current_window:
                del self.request_counts[window]

        # Allow request if under limit
        if self.request_counts[current_window] < self.max_requests:
            self.request_counts[current_window] += 1
            return True

        return False
